import {KEY,today,shift,uid,weekdays,weekStart,periodTimes,lessonsOn,subjectTone,seed,addSampleActivity,load,persist,className,person,teacher,roster,assigned,visibleClasses,isSchoolDay,attendanceError,saveAttendance,transfer,balance,addPayment,saveSlot,log} from './model.js';
                                            
import {icon,dashboard} from './dashboard.js';
const root=document.querySelector('#app')               ,modal=document.querySelector('#modal')                     ;
const esc=(v    )=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c] ));
const money=(n       )=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
