const labels                      ={overview:'Overview',attendance:'Attendance',students:'Students & classes',fees:'Fees & receipts',timetable:'Timetable',allocation:'Teacher allocation',messages:'Parent communication',performance:'Performance',settings:'School settings'};
let s      ,role='admin',teacherId='t0',classId='c10',page='overview',date=today(),draft                     ={},draftKey='',dirty=false,correcting=false,stale=false,query='',activeSubmit    =null,rangeDays=7;
let viewedWeek=weekStart(today());
const themeKey='schoolhouse-theme';
const navigationKey='schoolhouse-navigation';
let compactNav=false;
try{compactNav=localStorage.getItem(navigationKey)==='compact';}catch{}
let theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
try{const saved=localStorage.getItem(themeKey);if(saved==='dark'||saved==='light')theme=saved;}catch{}
function applyTheme(){document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#000000':'#eef2f7');}
applyTheme();
try{s=load(localStorage);}catch(e){root.innerHTML=`<main class="recovery"><div class="brand-mark"><img class="bellora-art" src="./assets/bellora-mark.svg" alt="Bellora" width="32" height="32"></div><h1>Let’s recover your workspace.</h1><p>${esc((e         ).message)}</p><p>Your stored data has not been overwritten. You can reload, or explicitly replace this workspace’s records with sample data.</p><button id="recover-reload">Reload</button> <button id="recover-reset">Reset sample data</button></main>`;document.querySelector('#recover-reload') .addEventListener('click',()=>location.reload());document.querySelector('#recover-reset') .addEventListener('click',()=>{if(confirm('Replace this workspace’s saved records with sample data?')){try{localStorage.setItem(KEY,JSON.stringify(seed()));location.reload();}catch{alert('Browser storage is unavailable. Allow local storage, then reload.');}}});}
function toast(text       ){const el=document.querySelector('#toast') ;el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4200);}
const button=(text       ,act       ,id='',cls='')=>`<button class="${cls}" data-act="${act}" data-id="${esc(id)}">${text}</button>`;
const badge=(text       ,tone='')=>`<span class="badge ${tone}">${esc(text)}</span>`;
function empty(title       ,detail       ){return `<div class="empty"><span>○</span><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;}
function option(value    ,text    ,selected    =''){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(text)}</option>`;}
function classOptions(selected=classId){return s.classes.filter(c=>!c.archived).map(c=>option(c.id,className(s,c.id),selected)).join('');}
function field(label       ,name       ,type='text',value    ='',extra=''){return `<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label       ,name       ,options       ){return `<label class="field">${esc(label)}<select name="${name}">${options}</select></label>`;}
function textField(label       ,name       ,value=''){return `<label class="field">${esc(label)}<textarea name="${name}" required rows="4">${esc(value)}</textarea></label>`;}
function dialog(title       ,body       ,submit       ,handler    ){activeSubmit=handler;modal.innerHTML=`<form id="dialog-form"><div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button type="button" data-close aria-label="Close dialog" class="icon-button">×</button></div><div class="dialog-body">${body}<p id="form-error" role="alert"></p></div><div class="dialog-foot"><button type="button" data-close>Cancel</button><button class="primary" type="submit">${esc(submit)}</button></div></form>`;modal.setAttribute('aria-labelledby','dialog-title');modal.showModal();}
function commit(message       ,fn                ){if(stale)throw Error('This workspace changed in another tab. Reload before editing.');const next=structuredClone(s);fn(next);log(next,message);persist(localStorage,next,s.revision);s=next;toast(message);}
function academic(){if(s.school.closed)throw Error('The academic year is closed. Reopen it in School settings to make changes.');}
function mutate(message       ,fn                ){academic();if(s.classes.find(c=>c.id===classId)?.archived)throw Error('Choose an active class to make changes.');commit(message,fn);}
function download(name       ,text       ,type='text/csv'){
 const url=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));
 dialog('Export ready',`<p>Review your file, then save it or copy its contents.</p><div class="export-actions"><a class="primary download-link" href="${url}" download="${esc(name)}">${icon('export')} Save file</a><button type="button" id="copy-export">Copy contents</button></div><label class="field">${esc(name)}<textarea id="export-content" rows="10" readonly spellcheck="false">${esc(text)}</textarea></label><p id="export-feedback" role="status"></p>`,'Done',()=>modal.close());
 document.querySelector('#copy-export') .addEventListener('click',async()=>{const feedback=document.querySelector('#export-feedback') ;try{await navigator.clipboard.writeText(text);feedback.textContent='Copied to clipboard';}catch{const area=document.querySelector                     ('#export-content') ;area.focus();area.select();feedback.textContent='Press Ctrl+C or Cmd+C to copy the selected contents.';}});
 modal.addEventListener('close',()=>setTimeout(()=>URL.revokeObjectURL(url),1000),{once:true});
}
function csv(rows        ){return rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');}
function ensureDraft(){const key=classId+'|'+date;if(draftKey!==key){const rec=s.attendance.find(x=>x.classId===classId&&x.date===date);draft=rec?.status==='submitted'?structuredClone(rec.entries):Object.fromEntries(roster(s,classId,date).map(x=>[x.id,rec?.entries[x.id]||'']));draftKey=key;dirty=false;correcting=false;}}
function saveCurrent(submit=false,reason=''){commit(submit?'Attendance submitted':'Attendance saved',next=>{saveAttendance(next,classId,date,draft,submit,role,teacherId,reason);});dirty=false;draftKey='';}
function navigate(fn         ){if(!dirty){fn();render();return;}const submitted=s.attendance.some(a=>a.classId===classId&&a.date===date&&a.status==='submitted');dialog('You have unsaved attendance',`<p>Save your changes, discard them, or stay on this screen.</p>${submitted?textField('Correction reason','reason'):''}<button type="button" id="discard">Discard changes and continue</button>`, 'Save and continue',(data         )=>{saveCurrent(submitted,String(data.get('reason')||''));fn();modal.close();render();});document.querySelector('#discard') .addEventListener('click',()=>{dirty=false;draftKey='';modal.close();fn();render();});}
function render(){
 const classes=role==='admin'?[...visibleClasses(s,role,teacherId),...s.classes.filter(c=>c.archived)]:visibleClasses(s,role,teacherId);
 if(!classes.some(c=>c.id===classId)){classId=classes[0]?.id||'';draftKey='';}ensureDraft();
 root.className=compactNav?'is-collapsed':'';
 const descriptions                      ={overview:'Your class at a glance. Attendance, lessons, and family updates.',attendance:'A daily check-in for every student in your class.',students:'Manage student records, enrollments, and class sections.',fees:'Track invoices, recorded payments, and outstanding balances.',timetable:'Plan weekly lessons, teachers, and classrooms.',allocation:'Connect teachers to classes and balance their teaching time.',messages:'Keep families connected with simulated class updates.',performance:'Record assessments and follow each student’s progress.',settings:'Manage your school details, academic year, and calendar.'};
 root.innerHTML=`<aside class="sidebar" id="school-navigation"><div class="brand-row"><span class="brand-mark"><img class="bellora-art" src="./assets/bellora-mark.svg" alt="Bellora" width="32" height="32"></span><strong aria-hidden="true"><img class="bellora-art bellora-wordmark" src="./assets/bellora-wordmark.svg" alt="" width="106" height="35"></strong><button class="close-navigation icon-button" data-act="close-navigation" aria-label="Close navigation">×</button></div><nav id="module-navigation" aria-label="Main navigation">${[['Workspace',['overview','students','attendance']],['School management',['timetable','allocation','fees','messages','performance']],['Administration',['settings']]].map(([group,items])=>{const available=(items            ).filter(k=>role==='admin'||!['fees','settings'].includes(k));return available.length?`<div class="sidebar-group"><p>${group}</p>${available.map(k=>`<button data-act="nav" data-id="${k}" class="nav-item ${page===k?'active':''}" aria-label="${labels[k]}" title="${labels[k]}" ${page===k?'aria-current="page"':''}>${icon(k)}<span class="nav-label">${({allocation:'Teachers',messages:'Messages',fees:'Fees & receipts',settings:'School settings'}                         )[k]||labels[k]}</span></button>`).join('')}</div>`:'';}).join('')}</nav><div class="sidebar-foot"><button class="collapse-navigation" data-act="collapse-navigation" aria-label="${compactNav?'Expand':'Collapse'} sidebar" title="${compactNav?'Expand':'Collapse'} sidebar" aria-controls="module-navigation" aria-expanded="${!compactNav}">${icon('collapse')}<span>${compactNav?'Expand':'Collapse'} sidebar</span></button></div></aside><button class="sidebar-scrim" data-act="close-navigation" aria-label="Close navigation overlay" tabindex="-1"></button>
 <div class="workspace"><header class="topbar"><div class="header-row"><div class="header-identity"><button class="open-navigation round-button" data-act="open-navigation" aria-label="Open navigation" aria-controls="school-navigation" aria-expanded="false">${icon('collapse')}</button><div class="workspace-name">${esc(s.school.name)}<span>${esc(s.school.start.slice(0,4))}–${esc(s.school.end.slice(2,4))} academic year</span></div></div><div class="top-actions"><button class="workspace-search round-button" data-act="workspace-search" aria-label="Search workspace" title="Search workspace (Ctrl K)">${icon('search')}</button><button class="theme-toggle round-button" data-act="theme" aria-label="Switch to ${theme==='dark'?'light':'dark'} mode" title="Switch to ${theme==='dark'?'light':'dark'} mode">${icon(theme==='dark'?'sun':'moon')}</button><label class="sr-only" for="role">Workspace role</label><select id="role"><option value="admin" ${role==='admin'?'selected':''}>Administrator</option><option value="teacher" ${role==='teacher'?'selected':''}>Teacher</option></select>${role==='teacher'?`<label class="sr-only" for="teacher">Teacher</label><select id="teacher">${s.teachers.map(t=>option(t.id,t.name,teacherId)).join('')}</select>`:''}<button class="avatar" data-act="profile" aria-label="Workspace profile">${role==='admin'?'AD':esc(teacher(s,teacherId).split(' ').map(x=>x[0]).join(''))}</button></div></div></header>
 <main class="${page==='overview'?'overview-page':''}"><div class="page-heading"><div>${page==='overview'&&role==='admin'?'':`<p class="eyebrow">${role==='admin'?'School workspace':'Teacher workspace'}</p>`}<h1>${page==='overview'?'School overview':labels[page]}</h1><p class="subheading">${descriptions[page]}</p></div><div class="heading-actions">${page==='overview'?button(icon('export')+' Export report','export-overview','','outline-button'): `<span class="date-pill">${icon('timetable')} ${dateLabel(today())}</span>`}</div></div>
 <div class="context"><div class="class-context">${icon('students')}<label for="class">Class workspace</label><select id="class">${classes.length?classes.map(c=>option(c.id,className(s,c.id)+(c.archived?' (archived)':''),classId)).join(''):'<option value="">No assigned classes</option>'}</select><span class="context-count">${roster(s,classId,today()).length} student${roster(s,classId,today()).length===1?'':'s'}</span></div><div class="context-actions">${page==='overview'?`<label for="dashboard-range" class="sr-only">Report range</label><select id="dashboard-range">${[7,30].map(n=>option(n,'Last '+n+' days',rangeDays)).join('')}</select>`:''}${role==='admin'&&page==='students'?button(icon('plus')+' Add class','add-class','','text-button'):''}</div></div>
 ${stale?'<div class="notice warning">Another tab changed this workspace. Reload to continue safely. <button data-act="reload">Reload workspace</button></div>':''}
 <div id="page" data-page="${page}">${({overview:overview,attendance:attendance,students:studentsPage,fees:feesPage,timetable:timetablePage,allocation:allocationPage,messages:messagesPage,performance:performancePage,settings:settingsPage}[page]) ()}${page==='attendance'&&role==='admin'?schoolRegisters():''}</div>
 <footer class="footer"><span><i class="local-dot"></i> Saved on this device</span><span>Bellora · ${dateLabel(today())}</span></footer></main></div>`;
 setSidebar(false,false);
 enhanceWorkspaceSelects();
 if(query){let found=0;root.querySelectorAll             ('[data-search]').forEach(row=>{row.hidden=!row.dataset.search .includes(query);if(!row.hidden)found++;});const noMatches=root.querySelector             ('.empty-search');if(noMatches)noMatches.hidden=found>0;}
}


function setSidebar(open        ,restoreFocus=true){
 const sidebar=root.querySelector             ('.sidebar'),workspace=root.querySelector             ('.workspace'),trigger=root.querySelector             ('[data-act="open-navigation"]');
 if(!sidebar||!workspace)return;
 const mobile=window.matchMedia('(max-width: 900px)').matches;
 root.classList.toggle('navigation-open',open&&mobile);workspace.inert=open&&mobile;sidebar.inert=mobile&&!open;
 trigger?.setAttribute('aria-expanded',String(open&&mobile));
 if(open&&mobile){sidebar.setAttribute('aria-modal','true');sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-label','School navigation');document.body.style.overflow='hidden';const focusNavigation=()=>{if(root.classList.contains('navigation-open')&&!sidebar.contains(document.activeElement))sidebar.querySelector             ('[aria-current="page"]')?.focus();};requestAnimationFrame(focusNavigation);setTimeout(focusNavigation,220);}
 else{sidebar.removeAttribute('role');sidebar.removeAttribute('aria-modal');sidebar.removeAttribute('aria-label');document.body.style.overflow='';if(restoreFocus&&mobile)trigger?.focus();}
}
window.addEventListener('resize',()=>setSidebar(false,false));
document.addEventListener('keydown',e=>{
 if(!root.classList.contains('navigation-open'))return;
 if(e.key==='Escape'){e.preventDefault();setSidebar(false);return;}
 if(e.key==='Tab'){const buttons=Array.from(root.querySelectorAll             ('.sidebar button')).filter(button=>button.getClientRects().length),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});

function closeSelectMenus(){
 root.querySelectorAll             ('.select-control.is-open').forEach(w=>{w.classList.remove('is-open');w.querySelector('[role="combobox"]')?.setAttribute('aria-expanded','false');w.querySelector('[role="combobox"]')?.removeAttribute('aria-activedescendant');(w.querySelector('[role="listbox"]')               ).hidden=true;});
}
function enhanceWorkspaceSelects(){
 root.querySelectorAll                   ('#role,#teacher,#class,#dashboard-range').forEach(select=>{
  const label=root.querySelector                  (`label[for="${select.id}"]`),name=label?.textContent||select.id,wrap=document.createElement('div');
  wrap.className='select-control';select.before(wrap);wrap.append(select);select.hidden=true;
  const trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.id=select.id+'-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label',name);trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls',select.id+'-options');trigger.innerHTML='<span>'+esc(select.selectedOptions[0]?.textContent||'Choose')+'</span>'+icon('chevron');wrap.append(trigger);if(label)label.htmlFor=trigger.id;
  const list=document.createElement('div');list.className='select-options';list.id=select.id+'-options';list.setAttribute('role','listbox');list.setAttribute('aria-label',name);list.hidden=true;wrap.append(list);
  const options=Array.from(select.options);let index=select.selectedIndex,typed='',typedAt=0;
  list.innerHTML=options.map((o,i)=>`<div role="option" id="${select.id}-option-${i}" aria-selected="${o.selected}" data-option="${i}"><span>${esc(o.textContent)}</span>${o.selected?icon('check'):''}</div>`).join('');
  function highlight(){list.querySelectorAll             ('[role="option"]').forEach((o,i)=>o.classList.toggle('is-focused',i===index));trigger.setAttribute('aria-activedescendant',select.id+'-option-'+index);list.children[index]?.scrollIntoView({block:'nearest'});}
  function open(){closeSelectMenus();list.hidden=false;wrap.classList.add('is-open');trigger.setAttribute('aria-expanded','true');index=select.selectedIndex;highlight();}
  function choose(){const next=options[index];if(!next)return;select.value=next.value;trigger.querySelector('span') .textContent=next.textContent;closeSelectMenus();select.dispatchEvent(new Event('change',{bubbles:true}));if(wrap.isConnected){trigger.querySelector('span') .textContent=select.selectedOptions[0]?.textContent||'Choose';list.querySelectorAll             ('[role="option"]').forEach((o,i)=>{o.setAttribute('aria-selected',String(i===select.selectedIndex));o.innerHTML='<span>'+esc(options[i].textContent)+'</span>'+(i===select.selectedIndex?icon('check'):'');});}if(!modal.open)document.getElementById(trigger.id)?.focus();}
  trigger.addEventListener('click',()=>list.hidden?open():closeSelectMenus());
  trigger.addEventListener('keydown',e=>{
   if(e.key==='Escape'){e.preventDefault();closeSelectMenus();return;}
   if(e.key==='Tab'){closeSelectMenus();return;}
   if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();if(list.hidden){open();return;}index=e.key==='Home'?0:e.key==='End'?options.length-1:Math.max(0,Math.min(options.length-1,index+(e.key==='ArrowDown'?1:-1)));highlight();return;}
   if(e.key==='Enter'||e.key===' '&&!typed){e.preventDefault();if(list.hidden)open();else choose();return;}
   if(e.key.length===1&&!e.ctrlKey&&!e.metaKey){e.preventDefault();if(list.hidden)open();typed=Date.now()-typedAt>700?e.key:typed+e.key;typedAt=Date.now();const match=options.findIndex(o=>o.text.toLowerCase().startsWith(typed.toLowerCase()));if(match>=0){index=match;highlight();}}
  });
  list.addEventListener('mousedown',e=>e.preventDefault());
  list.addEventListener('click',e=>{const option=(e.target               ).closest             ('[data-option]');if(option){index=Number(option.dataset.option);choose();}});
 });
}
document.addEventListener('click',e=>{if(!(e.target               ).closest('.select-control'))closeSelectMenus();});

function overview(){return dashboard(s,classId,role,rangeDays);}
function workspaceSearch(){
 const items=Object.entries(labels).filter(([key])=>role==='admin'||!['fees','settings'].includes(key));
 dialog('Search workspace',`<label class="field">Find a page or class<input id="command-search" type="search" placeholder="Try attendance, fees, or Class 6..."></label><div class="command-results">${items.map(([key,label])=>`<button type="button" data-command="${esc(label.toLowerCase())}" data-command-page="${key}">${icon(key)}<span>${esc(label)}</span>${icon('arrow')}</button>`).join('')}${visibleClasses(s,role,teacherId).map(c=>`<button type="button" data-command="${esc(className(s,c.id).toLowerCase())}" data-command-class="${c.id}">${icon('students')}<span>${esc(className(s,c.id))}</span><small>Class workspace</small></button>`).join('')}</div><p id="command-empty" hidden>No pages or classes match this search.</p>`,'Close',()=>modal.close());
 const input=document.querySelector                  ('#command-search') ;input.focus();input.addEventListener('input',()=>{let count=0;modal.querySelectorAll             ('[data-command]').forEach(el=>{el.hidden=!el.dataset.command .includes(input.value.toLowerCase());if(!el.hidden)count++;});document.querySelector             ('#command-empty') .hidden=count>0;});
 modal.querySelectorAll             ('[data-command]').forEach(el=>el.addEventListener('click',()=>{modal.close();navigate(()=>{if(el.dataset.commandPage)page=el.dataset.commandPage;else{classId=el.dataset.commandClass ;page='overview';draftKey='';}query='';});}));
}

function attendance(){const rec=s.attendance.find(a=>a.classId===classId&&a.date===date),locked=rec?.status==='submitted'&&!correcting,err=attendanceError(s,classId,date,role,teacherId),ids=rec?.status==='submitted'?Object.keys(rec.entries):roster(s,classId,date).map(x=>x.id);return `<section class="panel"><div class="panel-title"><div><h2>Class register</h2><p class="muted">${esc(className(s,classId))} · Once-daily attendance</p></div><div class="inline"><label class="date-field">Date <input id="att-date" type="date" value="${date}" min="${s.school.start}" max="${today()}"></label>${badge(rec?.status||'Not started',rec?.status==='submitted'?'mint':'sand')}${button('Export CSV','export-attendance')}</div></div>${err?`<div class="notice">${esc(err)}</div>`:''}<div class="attendance-counts" id="counts">${counts()}</div><div class="toolbar"><label class="search">⌕ <input id="search" placeholder="Search name or student ID" aria-label="Search students" value="${esc(query)}"></label>${!locked&&!err?button('Mark all present','mark-all','','text-button'):''}${locked&&!err?button('Correct attendance','correct','','primary'):''}</div><div class="table-wrap"><table class="attendance-table"><thead><tr><th>Student</th><th>Student ID</th><th>Attendance status</th></tr></thead><tbody>${ids.map(id=>{const st=s.students.find(x=>x.id===id) ;return `<tr data-search="${esc((st.name+' '+st.code).toLowerCase())}"><td><div class="person"><span class="student-avatar">${esc(st.name.split(' ').map(x=>x[0]).join(''))}</span><strong>${esc(st.name)}</strong></div></td><td class="muted">${esc(st.code)}</td><td><div class="status-controls" role="group" aria-label="Attendance for ${esc(st.name)}">${['present','absent','late'].map(v=>`<button data-mark="${v}" data-id="${id}" aria-pressed="${draft[id]===v}" class="mark ${v} ${draft[id]===v?'selected':''}" ${locked||err?'disabled':''}>${v==='present'?'✓':v==='absent'?'×':'◷'} ${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></td></tr>`;}).join('')}</tbody></table>${!ids.length?empty('No students for this date','Add or enroll students from Students & classes.'):''}<p class="empty-search" hidden>No students match your search.</p></div><div class="savebar"><span id="save-state">${dirty?'Unsaved changes':rec?'Saved in this browser':'Choose a status for each student'}</span><div>${!locked&&!err&&ids.length?`${correcting?'':button('Save draft','save-draft')}${button(correcting?'Save correction':'Submit attendance',correcting?'save-correction':'submit-attendance','','primary')}`:''}</div></div></section>
 <div class="two-col"><section class="panel"><h2>Attendance history</h2>${s.attendance.filter(x=>x.classId===classId&&(role==='admin'||assigned(s,teacherId,classId,x.date))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14).map(a=>`<button class="history-row" data-act="history" data-id="${a.date}"><span>${dateLabel(a.date)}</span>${badge(a.status,a.status==='submitted'?'mint':'sand')}<span>→</span></button>`).join('')||empty('No saved registers yet','Drafts and submitted attendance will appear here.')}</section><section class="panel"><h2>Correction history</h2>${rec?.audit.length?rec.audit.map(a=>`<div class="audit"><strong>${esc(a.actor)}</strong><small>${new Date(a.at).toLocaleString('en-IN')}</small><p>${esc(a.reason)}</p>${a.changes.map(c=>`<div class="muted">${esc(person(s,c.studentId))}: ${esc(c.before)} → ${esc(c.after)}</div>`).join('')}</div>`).join(''):empty('No corrections','Changes to submitted registers need a reason.')}</section></div>`;}
function counts(){return ['present','absent','late',''].map((v,i)=>`<div><span class="count-dot dot-${i}"></span><strong>${Object.values(draft).filter(x=>x===v).length}</strong><span>${v||'unmarked'}</span></div>`).join('');}
function studentsPage(){const sts=roster(s,classId,today()),c=s.classes.find(x=>x.id===classId);return `<section class="panel"><div class="panel-title"><div><h2>Class roster</h2><p class="muted">${sts.length} enrolled students · ${esc(className(s,classId))}</p></div><div class="inline">${role==='admin'?button('+ Add student','add-student','','primary'):''}</div></div><div class="toolbar"><label class="search">⌕ <input id="search" aria-label="Search students" placeholder="Search name or student ID"></label>${role==='admin'&&c?button('Archive class','archive-class',c.id,'text-button'):''}</div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Student ID</th><th>Enrollment</th><th>Actions</th></tr></thead><tbody>${sts.map(st=>`<tr data-search="${esc((st.name+' '+st.code).toLowerCase())}"><td><div class="person"><span class="student-avatar">${esc(st.name[0])}</span><strong>${esc(st.name)}</strong></div></td><td>${esc(st.code)}</td><td>${badge('Enrolled','mint')}</td><td>${role==='admin'?button('Edit','edit-student',st.id,'text-button')+button('Transfer','transfer',st.id,'text-button')+button('Archive','archive-student',st.id,'text-button'):badge('Teacher view')}</td></tr>`).join('')}</tbody></table>${!sts.length?empty('No students enrolled','Add your first student using the button above.'):''}<p class="empty-search" hidden>No students match your search.</p></div></section><div class="notice">Student transfers preserve previous attendance. Archived students stay in historical records.</div>`;}
function feesPage(){const invoices=s.invoices.filter(i=>(i.classId||s.students.find(st=>st.id===i.studentId)?.enrollments[0]?.classId)===classId),total=invoices.reduce((n,i)=>n+i.amount,0),due=invoices.reduce((n,i)=>n+balance(s,i),0);return `<div class="notice simulation">Payments and receipts are simulated; no money is collected.</div><div class="stats three"><article class="stat"><span>Total invoiced</span><strong>${money(total)}</strong></article><article class="stat"><span>Recorded payments</span><strong>${money(total-due)}</strong></article><article class="stat"><span>Outstanding</span><strong>${money(due)}</strong></article></div><section class="panel"><div class="panel-title"><h2>Class fee ledger</h2>${button('+ Create class fee','add-fee','','primary')}</div><div class="table-wrap"><table><thead><tr><th>Student / fee</th><th>Amount</th><th>Due date</th><th>Balance</th><th>Actions</th></tr></thead><tbody>${invoices.map(i=>`<tr><td><strong>${esc(person(s,i.studentId))}</strong><small>${esc(i.title)}</small></td><td>${money(i.amount)}</td><td>${dateLabel(i.due)}</td><td>${badge(balance(s,i)===0?'Paid':money(balance(s,i)),balance(s,i)===0?'mint':'sand')}</td><td>${balance(s,i)>0?button('Record payment','pay',i.id,'text-button'):''}${button('Receipts','receipts',i.id,'text-button')}</td></tr>`).join('')}</tbody></table>${!invoices.length?empty('A clean ledger','Create a fee for the students in this class.'):''}</div></section>`;}
function timetablePage(){
 const now=today(),end=shift(viewedWeek,4),weekDates=weekdays.map((day,i)=>({day,date:shift(viewedWeek,i)})),short=(d       )=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
 const week=weekDates.map(d=>({...d,open:isSchoolDay(s,d.date),lessons:lessonsOn(s,classId,d.date)}));
 const subjects=[...new Set(week.flatMap(d=>d.lessons.map(x=>x.subject          )))].sort();
 return `<section class="panel timetable-panel"><div class="panel-title timetable-heading"><div><h2>Weekly timetable</h2><p class="muted">${esc(className(s,classId))} · Six periods per teaching day</p></div>${role==='admin'?button(icon('plus')+' Add lesson','add-slot','','primary'):''}</div>
 <div class="week-toolbar"><div class="week-label" aria-live="polite">${icon('timetable')}<strong>${short(viewedWeek)} – ${short(end)} ${end.slice(0,4)}</strong>${viewedWeek===weekStart(now)?'<span>This week</span>':''}</div><div class="week-controls" aria-label="Choose timetable week"><button type="button" class="week-arrow previous" data-act="week-prev" aria-label="Previous week">${icon('chevron')}</button>${button('Today','week-today','','week-today')}<button type="button" class="week-arrow" data-act="week-next" aria-label="Next week">${icon('chevron')}</button></div></div>
 <div class="week-scroll" tabindex="0" role="region" aria-label="Weekly lesson grid"><table class="timetable-table"><thead><tr><th scope="col">Time</th>${week.map(d=>`<th scope="col" ${d.date===now?'data-today="true"':''}><span>${d.day}</span><time datetime="${d.date}" ${d.date===now?'aria-current="date"':''}>${short(d.date)}</time>${d.open?'':'<small>Closed</small>'}</th>`).join('')}</tr></thead><tbody>${periodTimes.map((time,i)=>`<tr><th scope="row">${time}<small>Period ${i+1}</small></th>${week.map(d=>{
  const x=d.lessons.find(l=>l.period===i+1),tag=role==='admin'?'button':'div';
  return `<td ${d.date===now?'data-today="true"':''} ${d.open?'':'data-closed="true"'}>${x?`<${tag} class="lesson-card subject-tone-${subjectTone(x.subject)}" ${role==='admin'?`data-act="edit-slot" data-id="${esc(x.id)}" aria-label="Edit ${esc(x.subject)}, ${d.day}, ${time}"`:''}><strong>${esc(x.subject)}</strong><small>${esc(teacher(s,x.teacherId))}</small><span>${esc(x.room)}</span></${tag}>`:`<span class="free-period" aria-label="${d.open?'No lesson':'School closed'}">—</span>`}</td>`;
 }).join('')}</tr>`).join('')}</tbody></table></div>
 ${subjects.length?`<div class="subject-key" aria-label="Subjects">${subjects.map(subject=>`<span class="subject-tone-${subjectTone(subject)}"><i aria-hidden="true"></i>${esc(subject)}</span>`).join('')}</div>`:''}<p class="timetable-note">Lessons repeat weekly and respect the school calendar and teacher assignment dates. Editing a lesson changes its weekly slot.</p></section>`;
}
function allocationPage(){return `<section class="panel"><div class="panel-title"><div><h2>Teacher assignments</h2><p class="muted">Assignments and weekly teaching load across the school</p></div><div class="inline">${role==='admin'?button('+ Add teacher','add-teacher')+button('+ Assign teacher','add-allocation','','primary'):''}</div></div><div class="teacher-grid">${s.teachers.filter(t=>role==='admin'||t.id===teacherId).map(t=>{const allocations=s.allocations.filter(a=>a.teacherId===t.id&&a.start<=today()&&today()<=a.end);return `<article class="teacher-card"><span class="teacher-avatar">${esc(t.name.split(' ').map(x=>x[0]).join(''))}</span><h3>${esc(t.name)}</h3><p>${allocations.length} class subjects · ${s.slots.filter(x=>x.teacherId===t.id).length} lessons / week</p><div class="allocation-list">${allocations.map(a=>`<div><span>${esc(className(s,a.classId))}<small>${esc(a.subject)}</small></span>${role==='admin'?button('End','end-allocation',a.id,'text-button'):''}</div>`).join('')||'<span class="muted">No current assignments</span>'}</div></article>`;}).join('')}</div></section>`;}
function messagesPage(){const messages=s.messages.filter(m=>m.classId===classId);return `<div class="notice simulation">Sending and acknowledgements are simulated; nothing is delivered.</div><section class="panel"><div class="panel-title"><div><h2>A bridge between school and home</h2><p class="muted">Updates for ${esc(className(s,classId))}</p></div>${button('+ Compose update','compose','','primary')}</div><div class="message-list">${messages.map(m=>`<article class="message-card"><div class="message-icon">✉</div><div class="message-content"><div class="panel-title"><h3>${esc(m.title)}</h3>${badge(m.status,m.status==='Draft'?'sand':'mint')}</div><p class="message-body">${esc(m.body)}</p><div class="message-meta">${dateLabel(m.date)} · ${m.studentId?esc(person(s,m.studentId))+' family':m.recipients.length+' families'} ${m.acknowledged?'· Simulated acknowledgement':''}</div><div class="inline">${m.status==='Draft'?button('Edit draft','edit-message',m.id,'text-button')+button('Simulate send','send-message',m.id,'primary'):!m.acknowledged?button('Simulate acknowledgement','ack-message',m.id,'text-button'):''}</div></div></article>`).join('')||empty('Nothing sent, plenty to say','Compose your first update. Save it as a draft or simulate sending.')}</div></section>`;}
function performancePage(){const assessments=s.assessments.filter(a=>a.classId===classId),sts=roster(s,classId,today());return `<section class="panel"><div class="panel-title"><div><h2>Assessments and scores</h2><p class="muted">Assessment scores and individual progress</p></div>${button('+ Add assessment','add-assessment','','primary')}</div><div class="assessment-strip">${assessments.map(a=>{const vals=Object.values(a.scores).filter(v=>v!==null)            ,avg=vals.length?Math.round(vals.reduce((n,v)=>n+v,0)/vals.length/a.max*100):null;return `<button class="assessment-card" data-act="scores" data-id="${a.id}"><span class="tiny-label">${esc(a.subject)}</span><h3>${esc(a.title)}</h3><strong>${avg===null?'—':avg+'%'}<small>class average</small></strong><span>${vals.length} scored · out of ${a.max} points</span><b>Enter scores →</b></button>`;}).join('')||empty('No assessments yet','Add an assessment to start recording scores.')}</div><div class="table-wrap"><table><thead><tr><th>Student</th>${assessments.map(a=>`<th>${esc(a.title)}<small>/${a.max}</small></th>`).join('')}<th>Average</th></tr></thead><tbody>${sts.map(st=>{const values=assessments.filter(a=>a.scores[st.id]!=null).map(a=>a.scores[st.id]/a.max*100),avg=values.length?Math.round(values.reduce((a,b)=>a+b,0)/values.length):null;return `<tr><td><strong>${esc(st.name)}</strong><small>${esc(st.code)}</small></td>${assessments.map(a=>`<td>${a.scores[st.id]??'—'}</td>`).join('')}<td>${avg===null?'Not assessed':`<div class="progress-row"><div class="progress-track"><span style="width:${avg}%"></span></div><strong>${avg}%</strong></div>`}</td></tr>`;}).join('')}</tbody></table></div><p class="muted">Average of available assessment percentages. Missing scores are not counted as zero.</p></section>`;}
function schoolRegisters(){return `<section class="panel"><div class="panel-title"><h2>Across the school</h2><span class="muted">${dateLabel(date)} · Saved registers</span></div><div class="table-wrap"><table><thead><tr><th>Class</th><th>Roster</th><th>Present / late</th><th>Submission</th><th></th></tr></thead><tbody>${s.classes.filter(c=>!c.archived).map(c=>{const a=s.attendance.find(a=>a.classId===c.id&&a.date===date),count=a?Object.keys(a.entries).length:roster(s,c.id,date).length,expected=isSchoolDay(s,date)&&count>0,status=a?.status||(expected?'Missing':'Not expected');return `<tr><td>${esc(className(s,c.id))}</td><td>${count}</td><td>${a?Object.values(a.entries).filter(x=>x==='present'||x==='late').length:'—'}</td><td>${badge(status,status==='submitted'?'mint':expected?'sand':'')}</td><td>${button('Open register','register-class',c.id,'text-button')}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
function settingsPage(){return `<div class="two-col"><section class="panel"><h2>School & academic year</h2><form id="settings-form">${field('School name','name','text',s.school.name,'required maxlength="80"')}${field('Academic year starts','start','date',s.school.start,'required')}${field('Academic year ends','end','date',s.school.end,'required')}<label class="field">Holidays (one YYYY-MM-DD date per line)<textarea name="holidays" rows="3">${s.school.holidays.join('\n')}</textarea></label><label class="field">Extra working days (one YYYY-MM-DD date per line)<textarea name="working" rows="3">${s.school.working.join('\n')}</textarea></label><label class="checkbox"><input type="checkbox" name="closed" ${s.school.closed?'checked':''}> Close academic year (read-only workflows)</label><p id="settings-error" role="alert"></p><button class="primary">Save settings</button></form></section><section class="panel"><h2>Storage & workspace</h2><div class="settings-note"><span class="stat-icon mint">⌂</span><h3>Your browser is the workspace</h3><p>This workspace uses sample school records. Changes stay in this browser on this address until you reset the records or clear site data. They do not sync across devices.</p><p>The role switch previews different workflows. It is not a secure sign-in. No payments, emails, or parent notifications are sent.</p></div>${button('Add recent sample activity','sample-activity','','outline-button')}<p class="muted">Add a month of fictional attendance, class updates and assessments to the original sample classes. Saved records are kept; classes you created or changed are skipped.</p>${button('Reset to sample data','reset','','danger')}<p class="muted">Reset affects this project only.</p></section></div>`;}

modal.addEventListener('click',e=>{if((e.target               ).closest('[data-close]'))modal.close();});
modal.addEventListener('submit',e=>{e.preventDefault();try{activeSubmit(new FormData(e.target                   ));}catch(err){document.querySelector('#form-error') .textContent=(err         ).message;}});
root.addEventListener('change',e=>{const el=e.target                    ;if(el.id==='dashboard-range'){rangeDays=Number(el.value);render();return;}if(el.id==='role'){const v=el.value;navigate(()=>{role=v;if(role==='teacher'&&['fees','settings'].includes(page))page='overview';draftKey='';});el.value=role;}if(el.id==='teacher'){const v=el.value;navigate(()=>{teacherId=v;draftKey='';});el.value=teacherId;}if(el.id==='class'){const v=el.value;navigate(()=>{classId=v;draftKey='';query='';});el.value=classId;}if(el.id==='att-date'){const v=el.value;if(v)navigate(()=>{date=v;draftKey='';});el.value=date;}});
root.addEventListener('input',e=>{const el=e.target                    ;if(el.id==='search'){query=el.value.toLowerCase();let found=0;root.querySelectorAll             ('[data-search]').forEach(row=>{row.hidden=!row.dataset.search .includes(query);if(!row.hidden)found++;});const emptyEl=root.querySelector             ('.empty-search');if(emptyEl)emptyEl.hidden=found>0;}});
root.addEventListener('submit',e=>{if((e.target               ).id!=='settings-form')return;e.preventDefault();const d=new FormData(e.target                   );try{const start=String(d.get('start')),end=String(d.get('end'));if(start>=end)throw Error('The end date must be after the start date.');const parse=(key       )=>String(d.get(key)).split(/\s+/).filter(Boolean);const holidays=parse('holidays'),working=parse('working');if([...holidays,...working].some(v=>!/^\d{4}-\d{2}-\d{2}$/.test(v)||Number.isNaN(Date.parse(v))||new Date(v).toISOString().slice(0,10)!==v||v<start||v>end))throw Error('Calendar dates must be valid YYYY-MM-DD dates within the academic year.');if(holidays.some(v=>working.includes(v)))throw Error('A date cannot be both a holiday and an extra working day.');if(s.attendance.some(a=>a.date<start||a.date>end||holidays.includes(a.date)))throw Error('These dates conflict with saved attendance. Preserve the current calendar or reset the sample data.');commit('School settings updated',n=>{n.school={name:String(d.get('name')).trim(),start,end,closed:d.has('closed'),holidays,working};if(!n.school.name)throw Error('School name is required.');});render();}catch(err){document.querySelector('#settings-error') .textContent=(err         ).message;}});
root.addEventListener('click',e=>{const el=(e.target               ).closest             ('[data-act],[data-mark]');if(!el)return;e.preventDefault();if(el.dataset.mark){draft[el.dataset.id ]=el.dataset.mark         ;dirty=true;el.parentElement .querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el));});document.querySelector('#counts') .innerHTML=counts();document.querySelector('#save-state') .textContent='Unsaved changes';return;}try{action(el.dataset.act ,el.dataset.id||'');}catch(err){toast((err         ).message);}});
function done(){modal.close();render();}
function action(act       ,id       ){
 if(['week-prev','week-next','week-today'].includes(act)){viewedWeek=act==='week-today'?weekStart(today()):shift(viewedWeek,act==='week-prev'?-7:7);render();root.querySelector             (`[data-act="${act}"]`)?.focus({preventScroll:true});return;}
 if(act==='sample-activity'){academic();const preview=structuredClone(s),count=addSampleActivity(preview);if(!count){toast('Sample activity is already up to date, or no unchanged sample classes remain.');return;}dialog('Add recent school activity',`<p>Add ${count} fictional sample records across the original sample classes, including recent attendance, class updates and assessments.</p><p>Existing attendance, payments, messages and lesson schedules will be kept. Custom or changed class rosters are skipped. No real messages or payments are sent.</p>`,'Add sample activity',()=>{commit('Sample school activity added',n=>addSampleActivity(n));draftKey='';page='overview';done();});return;}
 if(act==='theme'){theme=theme==='dark'?'light':'dark';applyTheme();try{localStorage.setItem(themeKey,theme);}catch{toast('Appearance changed for this session. Browser storage is unavailable.');}root.querySelectorAll             ('[data-act="theme"]').forEach(el=>{const label=`Switch to ${theme==='dark'?'light':'dark'} mode`;el.setAttribute('aria-label',label);el.title=label;el.innerHTML=icon(theme==='dark'?'sun':'moon')+(el.classList.contains('rail-theme')?`<span>${theme==='dark'?'Light':'Dark'} mode</span>`:'');});return;}
 if(act==='profile'){dialog('Workspace profile',`<div class="profile-summary"><span class="teacher-avatar">${role==='admin'?'AD':esc(teacher(s,teacherId).split(' ').map(x=>x[0]).join(''))}</span><h3>${role==='admin'?'Administrator':esc(teacher(s,teacherId))}</h3><p>${esc(s.school.name)} · ${role==='admin'?'School administration':'Teacher workspace'}</p></div><p>Records are saved in this browser. The role selector switches workspace views; it is not a secure sign-in. Payments and parent messages are simulations.</p>`,'Done',()=>modal.close());return;}
 if(act==='collapse-navigation'){compactNav=!compactNav;root.classList.toggle('is-collapsed',compactNav);const control=root.querySelector             ('[data-act="collapse-navigation"]') ;control.setAttribute('aria-label',compactNav?'Expand sidebar':'Collapse sidebar');control.setAttribute('aria-expanded',String(!compactNav));control.title=compactNav?'Expand sidebar':'Collapse sidebar';control.querySelector('span') .textContent=control.title;try{localStorage.setItem(navigationKey,compactNav?'compact':'expanded');}catch{toast('Navigation changed for this session. Browser storage is unavailable.');}return;}
 if(act==='open-navigation'){setSidebar(true);return;}if(act==='close-navigation'){setSidebar(false);return;}
 if(act==='workspace-search'){workspaceSearch();return;}
 if(act==='export-overview'){const from=shift(today(),-rangeDays+1);const records=s.attendance.filter(a=>a.classId===classId&&a.date>=from&&a.date<=today());download('bellora-class-report.csv',csv([['Class','Date','State','Present','Late','Absent','Unmarked'],...records.map(a=>{const values=Object.values(a.entries);return [className(s,classId),a.date,a.status,...['present','late','absent',''].map(v=>values.filter(x=>x===v).length)];})]));toast('Class report ready');return;}
 if(act==='nav'){setSidebar(false,false);navigate(()=>{page=id;query='';});return;}if(act==='reload'){location.reload();return;}if(act==='go-attendance'){navigate(()=>{page='attendance';date=today();draftKey='';});return;}
 if(act==='reset'){dialog('A fresh start?', '<p>This replaces your saved classes, students, attendance, and all other records with fictional sample data. Only records in this browser workspace are affected.</p>', 'Reset sample data',()=>{const next=seed();localStorage.setItem(KEY,JSON.stringify(next));s=next;stale=false;dirty=false;draftKey='';classId='c10';page='overview';done();toast('Sample data restored');});return;}
 if(act==='register-class'){navigate(()=>{classId=id;draftKey='';query='';});return;}
 if(act==='history'){navigate(()=>{date=id;draftKey='';});return;}
 if(act==='mark-all'){for(const id of Object.keys(draft))draft[id]='present';dirty=true;render();return;}
 if(act==='correct'){correcting=true;render();return;}
 if(act==='save-draft'||act==='submit-attendance'){saveCurrent(act==='submit-attendance');render();return;}
 if(act==='save-correction'){dialog('Why is this register changing?',textField('Correction reason','reason'),'Save correction',d=>{saveCurrent(true,String(d.get('reason')));done();});return;}
 if(act==='export-attendance'){const rec=s.attendance.find(a=>a.classId===classId&&a.date===date);if(!rec)throw Error('Save the register before exporting.');download(`attendance-${date}.csv`,csv([['Class','Date','Student ID','Student','Status'],...Object.entries(rec.entries).map(([id,status])=>[className(s,classId),date,s.students.find(x=>x.id===id)?.code,person(s,id),status])]));return;}
 if(act==='add-class'){dialog('Make room for a new class',field('Class / grade','grade','number','', 'required min="1" max="12"')+field('Section','section','text','','required maxlength="12"'),'Create class',d=>{mutate('Class created',n=>{const grade=String(Number(d.get('grade'))),section=String(d.get('section')).trim().toUpperCase();if(!section||n.classes.some(c=>c.grade===grade&&c.section===section&&!c.archived))throw Error('This class and section already exists or is empty.');const c={id:uid(),grade,section,archived:false};n.classes.push(c);classId=c.id;});draftKey='';done();});return;}
 if(act==='add-student'||act==='edit-student'){const st=s.students.find(x=>x.id===id);dialog(st?'Edit student':'Welcome a new student',field('Full name','name','text',st?.name||'','required maxlength="80"')+field('Unique student ID','code','text',st?.code||'','required maxlength="30"')+(!st?selectField('Class','classId',classOptions())+field('Enrollment date','start','date',today(),`required min="${s.school.start}" max="${s.school.end}"`):''),'Save student',d=>{mutate(st?'Student updated':'Student added',n=>{const name=String(d.get('name')).trim(),code=String(d.get('code')).trim();if(!name||!code||n.students.some(x=>x.id!==id&&x.code.toLowerCase()===code.toLowerCase()))throw Error('Enter a name and a unique student ID.');if(st){Object.assign(n.students.find(x=>x.id===id) ,{name,code});}else{const c=String(d.get('classId')),start=String(d.get('start'));if(!c)throw Error('Create a class first.');if(n.attendance.some(a=>a.classId===c&&a.date>=start&&a.status==='submitted'))throw Error('Submitted attendance exists after this enrollment date. Choose a later date.');n.students.push({id:uid(),name,code,archived:false,enrollments:[{classId:c,start,end:''}]});}});draftKey='';done();});return;}
 if(act==='transfer'){dialog('Transfer student',`<p>${esc(person(s,id))} will keep their previous attendance history.</p>`+selectField('Destination class','to',classOptions())+field('Effective date','date','date',today(),`required min="${s.school.start}" max="${s.school.end}"`),'Transfer student',d=>{mutate('Student transferred',n=>transfer(n,id,String(d.get('to')),String(d.get('date'))));draftKey='';done();});return;}
 if(act==='archive-student'){dialog('Archive student',`<p>Remove ${esc(person(s,id))} from rosters starting tomorrow. Past attendance and fee records remain.</p>`,'Archive student',()=>{mutate('Student archived',n=>{const st=n.students.find(x=>x.id===id) ;st.archived=true;st.enrollments.filter(e=>!e.end).forEach(e=>e.end=shift(today(),1));});done();});return;}
 if(act==='archive-class'){dialog('Archive class', '<p>This class must have no current or future enrollments and no timetable lessons. Historical attendance stays readable by selecting the archived class.</p>','Archive class',()=>{mutate('Class archived',n=>{if(n.students.some(st=>st.enrollments.some(e=>e.classId===id&&(!e.end||e.end>today())))||n.slots.some(x=>x.classId===id))throw Error('Transfer/archive students and remove lessons before archiving this class.');n.classes.find(c=>c.id===id).archived=true;});draftKey='';done();});return;}
 if(act==='add-teacher'){dialog('Add a teacher',field('Full name','name','text','','required maxlength="80"'),'Add teacher',d=>{mutate('Teacher added',n=>{const name=String(d.get('name')).trim();if(!name)throw Error('A name is required.');n.teachers.push({id:uid(),name});});done();});return;}
 if(act==='add-allocation'){dialog('Assign a teacher',selectField('Teacher','teacherId',s.teachers.map(t=>option(t.id,t.name)).join(''))+selectField('Class','classId',classOptions())+field('Subject','subject','text','','required maxlength="50"')+field('Starts','start','date',today(),`required min="${s.school.start}" max="${s.school.end}"`)+field('Ends','end','date',s.school.end,`required min="${s.school.start}" max="${s.school.end}"`),'Save assignment',d=>{mutate('Teacher assigned',n=>{const a=Object.fromEntries(d)       ;a.id=uid();a.subject=a.subject.trim();if(!a.subject||!a.classId||a.start>a.end)throw Error('Choose a class, subject, and valid date range.');if(n.allocations.some(x=>x.classId===a.classId&&x.subject.toLowerCase()===a.subject.toLowerCase()&&x.start<=a.end&&a.start<=x.end))throw Error('This subject already has an overlapping class assignment.');n.allocations.push(a);});done();});return;}
 if(act==='end-allocation'){dialog('End this assignment', '<p>This ends the assignment yesterday and removes its future weekly timetable lessons. Saved attendance remains.</p>','End assignment',()=>{mutate('Teacher assignment ended',n=>{const a=n.allocations.find(x=>x.id===id);a.end=shift(today(),-1);n.slots=n.slots.filter(x=>!(x.classId===a.classId&&x.teacherId===a.teacherId&&x.subject===a.subject));});done();});return;}
 if(act==='add-slot'||act==='edit-slot'){const slot=s.slots.find(x=>x.id===id),alloc=s.allocations.filter(a=>a.classId===classId&&a.start<=today()&&today()<=a.end);dialog(slot?'Edit lesson':'Add a lesson',selectField('Subject & teacher','allocation',alloc.map(a=>option(a.id,`${a.subject} — ${teacher(s,a.teacherId)}`,slot?alloc.find(a=>a.subject===slot.subject&&a.teacherId===slot.teacherId)?.id:'')).join(''))+selectField('Day','day',weekdays.map(d=>option(d,d,slot?.day)).join(''))+selectField('Period','period',Array.from({length:6},(_,i)=>option(i+1,`Period ${i+1}`,slot?.period)).join(''))+field('Room','room','text',slot?.room||'','required maxlength="40"')+(slot?button('Remove lesson','remove-slot',id,'danger'):''),'Save lesson',d=>{mutate('Timetable updated',n=>{const a=n.allocations.find(x=>x.id===d.get('allocation'));if(!a)throw Error('Assign a teacher to this class first.');saveSlot(n,{id:slot?.id||uid(),classId,teacherId:a.teacherId,subject:a.subject,day:String(d.get('day')),period:Number(d.get('period')),room:String(d.get('room')).trim()});});done();});return;}
 if(act==='add-fee'){dialog('Create a class fee',`<p>Creates a fictional invoice for each of the ${roster(s,classId,today()).length} current students. No money will be collected.</p>`+field('Fee name','title','text','','required maxlength="80"')+field('Amount per student (INR)','amount','number','','required min="1" max="1000000" step="0.01"')+field('Due date','due','date',shift(today(),14),'required'),'Create invoices',d=>{mutate('Class fee created',n=>{const sts=roster(n,classId,today()),title=String(d.get('title')).trim();if(!sts.length||!title)throw Error('Add students and enter a fee name first.');if(n.invoices.some(i=>sts.some(st=>st.id===i.studentId)&&i.title.toLowerCase()===title.toLowerCase()))throw Error('A fee with this name already exists for this class.');for(const st of sts)n.invoices.push({id:uid(),classId,studentId:st.id,title,amount:Number(d.get('amount')),due:String(d.get('due'))});});done();});return;}
 if(act==='pay'){const inv=s.invoices.find(i=>i.id===id);dialog('Record a simulated payment',`<p>${esc(person(s,inv.studentId))} · ${esc(inv.title)}<br>Outstanding: ${money(balance(s,inv))}</p><div class="notice simulation">No real payment will be made.</div>`+field('Amount (INR)','amount','number',balance(s,inv),`required min="0.01" step="0.01" max="${balance(s,inv)}"`),'Record simulated payment',d=>{mutate('Simulated payment recorded',n=>addPayment(n,id,Number(d.get('amount'))));done();});return;}
 if(act==='receipts'){const inv=s.invoices.find(i=>i.id===id),ps=s.payments.filter(p=>p.invoiceId===id);dialog('Simulated receipts',`<p>${esc(person(s,inv.studentId))} · ${esc(inv.title)}</p>${ps.map(p=>`<div class="receipt-row"><div><strong>${money(p.amount)}</strong><small>${dateLabel(p.date)} · ${p.voided?'Voided: '+esc(p.reason):'Simulated payment'}</small></div><div>${button('Download','receipt-download',p.id,'text-button')}${!p.voided?button('Void','void-payment',p.id,'text-button'):''}</div></div>`).join('')||'<p>No payments have been recorded.</p>'}`,'Done',()=>modal.close());return;}
 if(act==='compose'||act==='edit-message'){const m=s.messages.find(m=>m.id===id);dialog(m?'Edit draft':'A note to families',selectField('Recipient','studentId',option('','All families in this class',m?.studentId)+roster(s,classId,today()).map(st=>option(st.id,st.name+' family',m?.studentId)).join(''))+field('Subject','title','text',m?.title||'','required maxlength="100"')+textField('Message','body',m?.body||''),'Save draft',d=>{mutate('Parent update saved as draft',n=>{const studentId=String(d.get('studentId')),recipients=studentId?[studentId]:roster(n,classId,today()).map(st=>st.id);if(!recipients.length)throw Error('This class has no families to select.');const title=String(d.get('title')).trim(),body=String(d.get('body')).trim();if(!title||!body)throw Error('Enter a subject and message.');const message={id:m?.id||uid(),classId,studentId,title,body,status:'Draft',recipients,date:today(),acknowledged:false};if(m)n.messages[n.messages.findIndex(x=>x.id===m.id)]=message;else n.messages.unshift(message);});done();});return;}
 if(act==='send-message'){mutate('Parent update simulated as sent',n=>{n.messages.find(m=>m.id===id).status='Simulated sent';});render();return;}
 if(act==='ack-message'){mutate('Acknowledgement simulated',n=>{n.messages.find(m=>m.id===id).acknowledged=true;});render();return;}
 if(act==='add-assessment'){dialog('Add an assessment',field('Title','title','text','','required maxlength="80"')+field('Subject','subject','text','','required maxlength="50"')+field('Maximum score','max','number',20,'required min="1" max="1000"')+field('Assessment date','date','date',today(),`required min="${s.school.start}" max="${today()}"`),'Create assessment',d=>{mutate('Assessment created',n=>{const title=String(d.get('title')).trim(),subject=String(d.get('subject')).trim(),sts=roster(n,classId,String(d.get('date')));if(!title||!subject||!sts.length)throw Error('Enter a title and subject for a class with enrolled students.');n.assessments.push({id:uid(),classId,title,subject,max:Number(d.get('max')),date:String(d.get('date')),scores:Object.fromEntries(sts.map(st=>[st.id,null]))});});done();});return;}
 if(act==='scores'){const a=s.assessments.find(a=>a.id===id);dialog(a.title,`<p>${esc(a.subject)} · out of ${a.max}. Leave a score blank for not assessed.</p><div class="score-fields">${Object.keys(a.scores).map(id=>field(person(s,id),id,'number',a.scores[id]??'',`min="0" max="${a.max}" step="0.5"`)).join('')}</div>`,'Save scores',d=>{mutate('Assessment scores saved',n=>{const a=n.assessments.find(x=>x.id===id);for(const id of Object.keys(a.scores)){const value=String(d.get(id));const number=value===''?null:Number(value);if(number!==null&&(!Number.isFinite(number)||number<0||number>a.max))throw Error('Scores must be within the assessment maximum.');a.scores[id]=number;}});done();});return;}
}
modal.addEventListener('click',e=>{const el=(e.target               ).closest             ('[data-act]');if(!el)return;e.preventDefault();const id=el.dataset.id ;try{if(el.dataset.act==='remove-slot'){mutate('Lesson removed',n=>{n.slots=n.slots.filter(x=>x.id!==id);});done();}if(el.dataset.act==='receipt-download'){const p=s.payments.find(x=>x.id===id),i=s.invoices.find(x=>x.id===p.invoiceId);download(`simulated-receipt-${p.id.slice(0,8)}.txt`,`SIMULATED RECEIPT — NO REAL PAYMENT\n${s.school.name}\nReceipt: ${p.id}\nStudent: ${person(s,i.studentId)}\nFee: ${i.title}\nAmount: ${money(p.amount)}\nDate: ${p.date}\nStatus: ${p.voided?'VOIDED — '+p.reason:'SIMULATED'}\n`,'text/plain');}if(el.dataset.act==='void-payment'){modal.close();dialog('Void simulated payment',textField('Reason','reason'),'Void payment',d=>{mutate('Simulated payment voided',n=>{const p=n.payments.find(x=>x.id===id);const reason=String(d.get('reason')).trim();if(!reason)throw Error('Enter a reason.');p.voided=true;p.reason=reason;});done();});}}catch(err){document.querySelector('#form-error') .textContent=(err         ).message;}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===KEY){stale=true;toast('Another tab changed this workspace. Reload before editing.');if(!dirty)render();}});
if(s )render();




document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!modal.open)workspaceSearch();}});
